-- HACKATHON ONLY (iterahq/hackathon-colosseum, Supabase nyzcbnnbffsizshiolbh)
-- 0260_itera_v2_english_content
--
-- What this does: rewrites the English side of the itera-v2 course (190 of 234 activities) so that, with the
-- language set to English, everything the learner reads, types or is graded on is English (demo site, starter
-- code, expected check text, blank answers, option labels, hints). The Portuguese side is unchanged, except
-- (a) "Samuel" in a sample page became "Tera" and (b) the "passe o mouse" prompt became pointer-neutral.
-- Text fields that were bare strings are now {"pt": <original>, "en": <english>} locale bags; the client and the
-- server grader collapse such bags to the active language before using the spec.
--
-- Additive and idempotent: the original spec of every touched row is saved once in
-- itera.activities_spec_backup_r2 (ON CONFLICT DO NOTHING keeps the first copy); each UPDATE just sets the spec,
-- so re-running it changes nothing. Rollback: update itera.activities a set spec = b.spec
-- from itera.activities_spec_backup_r2 b where b.activity_id = a.id;
-- Generated by /tmp/hk/r2/lesson/content/gen-sql.mjs from new-specs.json. Do not edit by hand.

create table if not exists itera.activities_spec_backup_r2 (
  activity_id uuid primary key,
  spec jsonb not null,
  saved_at timestamptz not null default now()
);
alter table itera.activities_spec_backup_r2 enable row level security;
revoke all on itera.activities_spec_backup_r2 from anon, authenticated;

insert into itera.activities_spec_backup_r2 (activity_id, spec)
